import math
def priority(task, state, m=5.0, b=1.0, p=0.5, q=0.0, alpha=1.0, backlog_q=0.0,
             t_align=1.0, t_var=1.0, t_sv=1.0):
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'alignment':
        tm = t_align
    elif task.task_type == 'variant_calling':
        tm = t_var
    else:
        tm = t_sv
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    wait = state.now - task.release
    backlog = state.queue_work / max(state.capacity, 1e-6)
    aging = 1.0 + b * wait / max((est ** alpha) * (cores ** q), 1e-6) * (1.0 + backlog_q * backlog)
    return tier * task.weight * tm / max(est * (cores ** p), 1e-6) * aging  # tuned (m=5.46,b=0.569,p=1.21,q=0,alpha=0.69,backlog_q=0,t_align=0.471,t_var=0.675,t_sv=3.33)

