def priority(task, state, m=5.0, k=2.0, a=1.0, b=0.5, align=1.0, variant=1.0, sv=1.0):
    if task.task_type == 'alignment':
        type_mult = align
    elif task.task_type == 'variant_calling':
        type_mult = variant
    else:
        type_mult = sv
    runtime = max(task.estimated_runtime * type_mult, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    expected_wait = state.queue_work / max(state.capacity, 1e-6)
    total_time = runtime + expected_wait
    time_to_due = task.due - state.now
    if time_to_due <= 0.0:
        urgency = 1.0 + a * (-time_to_due) / max(total_time, 1e-6)
    else:
        urgency = 1.0 / (1.0 + time_to_due / max(k * total_time, 1e-6))
    need = max(task.resource_need, 1e-6)
    penalty = 1.0 + b * need / max(state.free, 1e-6) * (state.queue_len / max(state.capacity, 1e-6))
    return tier * task.weight / runtime * urgency / max(penalty, 1e-6)  # tuned (m=3.55,k=3.7,a=0.376,b=1.75,align=1.25,variant=3.55,sv=0.894)

