def priority(task, state, m=5.0, b=0.5, rho=0.5, a_align=1.0, a_var=1.0, a_sv=1.0, f=0.0, rho2=0.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'alignment':
        tf = a_align
    elif task.task_type == 'variant_calling':
        tf = a_var
    else:
        tf = a_sv
    r = max(task.resource_need, 1e-6)
    cap = max(state.capacity, 1e-6)
    rf = max(r ** rho * (1.0 + rho2 * r / cap), 1e-6)
    eff = max(est * tf * rf, 1e-6)
    free = max(state.free, 0.0)
    if r <= free:
        fit = max(1.0 + f * (free - r) / cap, 1e-6)
    else:
        fit = 1.0 / max(1.0 + f * (r - free) / cap, 1e-6)
    return tier * task.weight / eff * (1.0 + b * wait / eff) * fit  # tuned (m=8.97,b=0.226,rho=0.306,a_align=0.538,a_var=1.33,a_sv=0.847,f=0,rho2=0)
